from collections import defaultdict
def f(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    seeds=defaultdict(list)
    for i in range(1,h):
        for j in range(w):
            if g[i][j]: seeds[g[i][j]].append((i,j))
    bar=[(j,g[0][j]) for j in range(w) if g[0][j]]
    for c,val in bar:
        if val in seeds:
            (sr,sc),=seeds[val]
            for r in range(sr+1): out[r][c]=val
            for cc in range(sc,c+1): out[sr][cc]=val
        else:
            for r in range(1,h): out[r][c]=val
    return out
